(window.IBALL_PERIODICAL_LIBRARY = window.IBALL_PERIODICAL_LIBRARY || {})["2026-07-13"] = {"meta":{"id":"2026-07-13","label":"2026 年 7 月 13 日","date":"2026-07-13","range":"","theme":"","themes":[],"sources":[],"title":"","titleZh":"","counts":{"article":0,"paragraph":0,"vocab":0,"question":15,"qa":0,"original":3,"layout":1},"tabs":{"articles":false,"reading":false,"tests":true,"qa":false,"originals":true}},"articles":[],"reading":[],"tests":[{"file":"【福利】7.13检验题__完型填空(1).docx","type":"cloze","instructions":["Directions: Read the following text. Choose the best word(s) for each numbered blank and mark A, B, C or D on the ANSWER SHEET. (10 points)"],"passage":["Section I Use of English","Passage","“The average parent does not post a picture of a child online thinking that it might be ____【11】____ to be turned into CSAM,” said an expert. “There are lots of parents who do not know that this problem exists.”","The IWF, which ____【12】____ such incidents and runs a reporting hotline, has been contacted by under-18s who have been blackmailed by extortionists after their images were nudified by AI. A confidential service for removing explicit images of under-18s taken without their ____【13】____, called Report Remove, has also reported examples of image manipulation involving normal, fully clothed selfies being converted into extreme pornography via AI.","In another case ____【14】____ by the Childline service, a 15-year-old girl said a stranger had made a “really convincing” fake nude of her that used her face and bedroom, having apparently taken the source material from her Instagram account.","The NCA and IWF guidance states: “If you’d like to share photos of your child online, we ____【15】____ creating a ‘close friends’ group or limiting visibility so only selected people can see them.” The children’s charity the NSPCC also ____【16】____ that under-18s keep their social media accounts on a private setting.","Videos released as part of the guidance show fictional ____【17】____ of parents taking photos of their children in everyday circumstances. The NCA and the IWF say they want to encourage parents and children to say “no” to sharing photos if they are ____【18】____ about it.","It also recommends ____【19】____ whether friends or family have uploaded images of your child in the post and discussing “clearly and calmly” what action could be taken with those posts. The guidance also suggests checking authorization forms signed by parents at school, nursery or clubs giving permission to use their child’s image, and considering whether they want to ____【20】____ that authorization."],"items":[{"number":11,"stem":"","options":[{"key":"A","text":"scraped"},{"key":"B","text":"collected"},{"key":"C","text":"gathered"},{"key":"D","text":"harvested"}],"answer":"A","kicker":"A (scraped)","analysis":["【题型】动词辨析(过去分词)·固定搭配","【难度】⭐⭐⭐⭐","【定位】Paragraph 1, 第1句","【解析】","[A] scraped（抡取/爬取）：正确答案。“scraped to be turned into CSAM”意为“被爬取并转化为虐儿素材”，scrape是互联网术语，表示“自动抓取网页图片”，是网络安全英语的标准用词。","[B] collected（收集）：近义干扰。collected语义可通，但偏向“人为收集”，不如scraped表达“自动爬取”精确。","[C] gathered（汇集）：近义干扰。gathered偏向“汇总”，不是网络数据抡取的专业表述。","[D] harvested（采集）：近义干扰。harvested语义可通，但多用于“harvesting data”，语气较广泛，不如scraped精确。"]},{"number":12,"stem":"","options":[{"key":"A","text":"tracks"},{"key":"B","text":"follows"},{"key":"C","text":"traces"},{"key":"D","text":"monitors"}],"answer":"D","kicker":"D (monitors)","analysis":["【题型】动词辨析·语境","【难度】⭐⭐⭐","【定位】Paragraph 2, 第1句","【解析】","[A] tracks（跟踪）：近义干扰。tracks语义可通，但偏向“追踪动态轨迹”，不如monitors表达“系统性监控”全面。","[B] follows（关注/跟随）：语义场干扰。follows偏向“关注动态”，语气较随意，不适合描述机构级别的全面监控。","[C] traces（追查）：语义场干扰。traces偏向“追溯来源”，强调回溯过去，不是持续监控。","[D] monitors（监控/监测）：正确答案。“monitors such incidents”意为“监控此类事件”，monitor表示“持续系统性地观察记录”，是新闻英语描述“机构监控”的高频用词。"]},{"number":13,"stem":"","options":[{"key":"A","text":"agreement"},{"key":"B","text":"approval"},{"key":"C","text":"permission"},{"key":"D","text":"consent"}],"answer":"D","kicker":"D (consent)","analysis":["【题型】名词辨析·固定搭配","【难度】⭐⭐⭐","【定位】Paragraph 2, 第2句","【解析】","[A] agreement（同意/协议）：近义干扰。agreement偏向“双方协商一致”，不如consent侧重“单方授权”精确。","[B] approval（批准）：近义干扰。approval偏向“上级批准”，与未成年人的自主授权语境不符。","[C] permission（允许）：近义干扰。permission语义可通，但“without permission”较为随意，不如“without consent”在法律语境中专业。","[D] consent（同意/授权）：正确答案。“images taken without their consent”意为“未经其同意拍摄的图片”，consent是法律/保护未成年人语境的标准术语，与后文“authorization forms”呼应。"]},{"number":14,"stem":"","options":[{"key":"A","text":"reported"},{"key":"B","text":"heard"},{"key":"C","text":"handled"},{"key":"D","text":"seen"}],"answer":"B","kicker":"B (heard)","analysis":["【题型】动词辨析(过去分词)·固定搭配","【难度】⭐⭐","【定位】Paragraph 3, 第1句","【解析】","[A] reported（报告）：近义干扰。reported语义可通，但“case reported by”偏向“被‖某人’报告”，与后文引述原文不符。","[B] heard（听取）：正确答案。“a case heard by the service”意为“该服务接待的一个案件”，heard是固定搭配，表示“服务机构听取/接待”，是新闻英语描述“客户服务案件”的高频用词。","[C] handled（处理）：近义干扰。handled语义可通，但“case handled by”偏向“被处理”，不如heard表达“服务接待”精确。","[D] seen（看到）：语义场干扰。seen过于随意，不适合描述服务机构的正式接待。"]},{"number":15,"stem":"","options":[{"key":"A","text":"urge"},{"key":"B","text":"recommend"},{"key":"C","text":"suggest"},{"key":"D","text":"advise"}],"answer":"C","kicker":"C (suggest)","analysis":["【题型】动词辨析·语境","【难度】⭐⭐⭐","【定位】Paragraph 4, 第1句","【解析】","[A] urge（敦促/强烈建议）：程度差异干扰。urge语气过于强烈，暗示紧急呼吁，与后文“we suggest”的较随和语气不符。","[B] recommend（推荐）：近义干扰。recommend语义接近，但偏向“正式推荐”，语气较为正式，不如suggest亲切。","[C] suggest（建议）：正确答案。“we suggest creating a close friends group”意为“我们建议创建亲密朋友组”，suggest语气中性友善，与引号内的建议语境匹配。","[D] advise（建议）：近义干扰。advise偏向“专业建议”，多用于专家对客户，语气较为正式。"]},{"number":16,"stem":"","options":[{"key":"A","text":"insists"},{"key":"B","text":"urges"},{"key":"C","text":"requires"},{"key":"D","text":"suggests"}],"answer":"C","kicker":"C (requires)","analysis":["【题型】动词辨析·语境","【难度】⭐⭐⭐","【定位】Paragraph 4, 第2句","【解析】","[A] insists（坚持要求）：逻辑方向干扰。insists语气过于强硬，暗示“坚持不让”，与慈善机构的建议语境不符。","[B] urges（敦促）：近义干扰。urges语义可通，但偏向“紧急呼吁”，语气较为强烈，不如requires表达“明确要求”精确。","[C] requires（要求）：正确答案。“requires that under-18s keep their accounts on a private setting”意为“要求未成年人保持私密设置”，require表示“明确要求/规定”，是慈善机构发布指南的标准用词。","[D] suggests（建议）：近义干扰。suggests语义可通，但偏向“较随和的建议”，与后文“keep on a private setting”的明确要求语气不符。"]},{"number":17,"stem":"","options":[{"key":"A","text":"scenes"},{"key":"B","text":"situations"},{"key":"C","text":"cases"},{"key":"D","text":"instances"}],"answer":"A","kicker":"A (scenes)","analysis":["【题型】名词辨析·语境","【难度】⭐⭐⭐","【定位】Paragraph 5, 第1句","【解析】","[A] scenes（场景/画面）：正确答案。“fictional scenes of parents taking photos”意为“父母拍照的虚构场景”，scenes表示“视频/画面中的具体场景”，与前文“Videos”呼应。","[B] situations（处境/情况）：近义干扰。situations偏向“抽象处境”，不适合描述视频中的具体画面。","[C] cases（案例）：语义场干扰。cases偏向“具体事件”，与视频中的场景描述不符。","[D] instances（实例）：语义场干扰。instances偏向“具体例子”，语气较为抽象，不适合描述视频场景。"]},{"number":18,"stem":"","options":[{"key":"A","text":"uneasy"},{"key":"B","text":"concerned"},{"key":"C","text":"worried"},{"key":"D","text":"uncomfortable"}],"answer":"D","kicker":"D (uncomfortable)","analysis":["【题型】形容词辨析·语境","【难度】⭐⭐⭐","【定位】Paragraph 5, 末句","【解析】","[A] uneasy（局促不安的）：近义干扰。uneasy语义可通，但偏向“心神不安”，语气较为抽象。","[B] concerned（担忧的）：近义干扰。concerned偏向“关切社会问题”，语气较为正式。","[C] worried（担心的）：近义干扰。worried偏向“担心后果”，强调未来不确定性。","[D] uncomfortable（不舒服的）：正确答案。“if they are uncomfortable about it”意为“如果他们对此感到不舒服”，uncomfortable表达“心理上的不自在”，与引号内“no”的拒绝语境匹配，是新闻英语描述“不愿意”的高频词。"]},{"number":19,"stem":"","options":[{"key":"A","text":"inspecting"},{"key":"B","text":"reviewing"},{"key":"C","text":"surveying"},{"key":"D","text":"screening"}],"answer":"B","kicker":"B (reviewing)","analysis":["【题型】动词辨析(现在分词)·语境","【难度】⭐⭐⭐","【定位】Paragraph 6, 第1句","【解析】","[A] inspecting（检查）：语义场干扰。inspecting偏向“正式检查/视察”，语气过于严肃，不适合描述家庭自查。","[B] reviewing（审查/回顾）：正确答案。“recommends reviewing whether friends or family have uploaded images”意为“建议检查朋友或家人是否上传了图片”，reviewing表示“仔细检查/回顾”，是指南类文档的高频词。","[C] surveying（调查）：语义场干扰。surveying偏向“统计调查”，语气过于学术化，不适合描述个人自查。","[D] screening（筛查）：语义场干扰。screening偏向“筛除不良内容”，语气过于专业，与家庭自查语境不符。"]},{"number":20,"stem":"","options":[{"key":"A","text":"revoke"},{"key":"B","text":"cancel"},{"key":"C","text":"withdraw"},{"key":"D","text":"remove"}],"answer":"C","kicker":"C (withdraw)","analysis":["【题型】动词辨析·语境","【难度】⭐⭐⭐⭐","【定位】Paragraph 6, 末句","【解析】","[A] revoke（废除/撤销）：近义干扰。revoke语义可通，但偏向“正式废除”，语气过于法律化，不如withdraw表达“主动撤回”自然。","[B] cancel（取消）：近义干扰。cancel偏向“取消预定计划”，多用于活动/订单，不适合描述授权。","[C] withdraw（撤销/撤回）：正确答案。“withdraw that authorization”意为“撤销该授权”，withdraw是“authorization/consent”的标准搭配，表示“主动撤回授权”，与前文“authorization forms”呼应。","[D] remove（移除）：语义场干扰。remove偏向“删除实物”，不是授权的标准搭配。","— — — — — — — — — —","本文档由我们自研的考研英语完型填空大模型生成。该模型基于近10年考研英语真题进行训练。我们会根据同学们的反馈持续优化模型能力。","本文档为【福利】，不提供答疑服务，欢迎大家自行交流使用。","【两个常见问题】","随着AI技术的不断进步，通过知识投喂和持续训练，大模型已逐渐具备模仿真题命题风格的能力。这份文档正是这一尝试的成果。它仅作为福利提供给大家，起到辅助检验的作用。你可以根据自身需要选择使用，如果有所顾虑，完全可以不用。"]}]},{"file":"【福利】7.13检验题__阅读理解(1).docx","type":"reading","instructions":[],"passage":[],"items":[{"number":21,"stem":"According to the IWF (Para.2), the amount of AI-generated CSAM found online _____ last year.","options":[{"key":"A","text":"decreased significantly due to improved detection"},{"key":"B","text":"rose by 14%, with 8,029 realistic AI-made images and videos identified in 2025"},{"key":"C","text":"remained roughly stable compared with previous years"},{"key":"D","text":"more than doubled compared with the year before"}],"answer":"B","kicker":"【答案】B","analysis":["【题型】细节理解题","【难度】⭐⭐","【定位】Paragraph 2","【解析】","- 原文（Para.2）：\"The amount of AI-generated CSAM found online rose by 14% last year, according to the IWF, which identified 8,029 realistic AI-made images and videos in 2025.\"","分析：","- 选项A：错误。使用了反义干扰陷阱。原文明确说\"rose by 14%\"（增长了14%），A 项\"decreased significantly\"（大幅下降）方向完全相反。","- 选项B：正确。Para.2 原文直接给出数据：\"rose by 14% last year... identified 8,029 realistic AI-made images and videos in 2025\"——去年增长14%，2025年识别出8,029个逼真的AI制作图片和视频。B 项精准复述该数据。","- 选项C：错误。使用了无中生有陷阱。原文说\"rose by 14%\"，并非\"remained roughly stable\"（基本稳定），C 项与数据矛盾。","- 选项D：错误。使用了过度推理陷阱。原文说\"rose by 14%\"，D 项\"more than doubled\"（翻了一番以上）将14%的增长夸大为100%以上，严重过度推理。"]},{"number":22,"stem":"The word \"nudified\" (Para.3) is closest in meaning to _____.","options":[{"key":"A","text":"enhanced in visual quality"},{"key":"B","text":"shared without permission on social media"},{"key":"C","text":"deleted permanently from online platforms"},{"key":"D","text":"digitally altered to appear naked"}],"answer":"D","kicker":"【答案】D","analysis":["【题型】词义猜测题","【难度】⭐⭐⭐","【定位】Paragraph 3","【解析】","- 原文（Para.3）：\"The IWF... has been contacted by under-18s who have been blackmailed by extortionists after their images were nudified by AI.\"","- 原文（Para.3）：\"normal, fully clothed selfies being converted into extreme pornography via AI\"","分析：","- 选项A：错误。使用了无中生有陷阱。\"enhanced in visual quality\"（在视觉质量上提升）与本段讨论的图像被篡改为色情内容的语境完全无关。","- 选项B：错误。使用了偷换概念陷阱。\"shared without permission\"（未经许可分享）描述的是传播行为，而 nudified 描述的是图像被AI篡改这一动作本身，二者是不同概念。","- 选项C：错误。使用了反义干扰陷阱。\"deleted permanently\"（永久删除）与原文语境完全矛盾——被 nudified 的图片不是被删除，而是被篡改成色情图片用于敲诈。","- 选项D：正确。\"nudify\"由\"nude\"（裸露）派生，意为\"使……裸露\"。Para.3 上下文：18岁以下青少年的图片\"were nudified by AI\"后被勒索者用来敲诈；后文进一步解释\"normal, fully clothed selfies being converted into extreme pornography\"（正常的衣着完整的自拍被转换为极端色情内容）。D 项\"digitally altered to appear naked\"（被数字化处理以显得裸露）精准对应。"]},{"number":23,"stem":"The author mentions the case of the 15-year-old girl (Para.4) in order to _____.","options":[{"key":"A","text":"illustrate how easily AI can create convincing fake explicit images from ordinary social media posts"},{"key":"B","text":"show that Instagram has weak security measures for teenage users"},{"key":"C","text":"criticize Childline for failing to protect vulnerable teenagers"},{"key":"D","text":"demonstrate that most strangers target children through physical contact rather than online"}],"answer":"A","kicker":"【答案】A","analysis":["【题型】例证题","【难度】⭐⭐⭐","【定位】Paragraph 4","【解析】","- 原文（Para.4）：\"In another case heard by the Childline service, a 15-year-old girl said a stranger had made a 'really convincing' fake nude of her that used her face and bedroom, having apparently taken the source material from her Instagram account.\"","分析：","- 选项A：正确。Para.4 举例一名15岁女孩的案例：陌生人用她的脸和卧室制作了\"really convincing\"（非常逼真的）伪造裸照，素材\"apparently taken from her Instagram account\"（显然取自她的Instagram账号）。该例证服务于全文论点——AI能轻易从普通社交媒体帖子中生成逼真的伪造色情图片，这正是促使NCA/IWF发布警告的核心原因。A 项精准概括该例证目的。","- 选项B：错误。使用了答非所问陷阱。原文确实提到素材取自Instagram，但这只是案例的事实细节，B 项将\"案例的事实\"升格为\"案例的目的\"，且\"Instagram 安保薄弱\"并非作者论证重点。","- 选项C：错误。使用了无中生有陷阱。原文说该案例是\"heard by the Childline service\"（由Childline热线受理），并未批评Childline失职，C 项捏造了作者对Childline的负面评价。","- 选项D：错误。使用了反义干扰陷阱。原文强调的是陌生人通过\"online\"（Instagram账号）而非线下物理接触实施侵害，D 项\"through physical contact rather than online\"将手段完全反转。"]},{"number":24,"stem":"Dan Sexton, the IWF's chief technology officer (Para.6), would most likely agree that _____.","options":[{"key":"A","text":"parents should feel free to share photos of their children on public platforms"},{"key":"B","text":"effective technical solutions already exist to prevent online image abuse"},{"key":"C","text":"advising parents against posting children's photos publicly is a regrettable but necessary measure"},{"key":"D","text":"the threat of AI-generated CSAM has been exaggerated by the media"}],"answer":"C","kicker":"【答案】C","analysis":["【题型】推理判断题·人物观点归属","【难度】⭐⭐⭐⭐","【定位】Paragraph 6","【解析】","- 原文（Para.6）：\"Dan Sexton, the IWF's chief technology officer, said he was 'very uncomfortable' about telling parents not to put pictures of children on public display but felt there was no other option.\"","- 原文（Para.6）：\"I would be very cautious [about putting pictures of children online] because there is no protection.\"","分析：","- 选项A：错误。使用了反义干扰陷阱。Dan Sexton 明确说\"I would be very cautious... because there is no protection\"（我会非常谨慎……因为没有任何保护），A 项\"freely share\"（自由分享）与其立场完全相反。","- 选项B：错误。使用了无中生有陷阱。Sexton 说\"there is no protection\"（没有保护），恰恰说明有效的技术防护方案尚不存在，B 项\"effective technical solutions already exist\"（已有有效技术方案）与其表述矛盾。","- 选项C：正确。Sexton 说自己\"very uncomfortable about telling parents not to put pictures of children on public display but felt there was no other option\"——对劝阻父母公开展示孩子照片感到\"非常不安\"，但\"觉得没有其他选择\"。这表明他认为该建议虽然令人遗憾（\"very uncomfortable\"），但却是必要的（\"no other option\"）。C 项\"regrettable but necessary measure\"（令人遗憾但必要的措施）精准概括其立场。","- 选项D：错误。使用了偷换概念陷阱。原文从未表明该威胁被\"exaggerated\"（夸大），相反Sexton 认为问题严重到\"没有其他选择\"，D 项将其态度偷换为轻视态度。"]},{"number":25,"stem":"Which of the following would be the best title for the text?","options":[{"key":"A","text":"How AI Is Revolutionizing Child Protection Online"},{"key":"B","text":"The Rise of AI-Generated Content on Social Media Platforms"},{"key":"C","text":"Why Parents Are Urged to Stop Sharing Children's Photos Online"},{"key":"D","text":"New Technologies for Detecting and Removing Online Child Abuse"}],"answer":"C","kicker":"【答案】C","analysis":["【题型】主旨大意题·标题概括","【难度】⭐⭐⭐⭐⭐","【定位】全文综合","【解析】","- 原文（Para.1）：\"The average parent or carer does not post a picture of a child online thinking that it might be scraped to be turned into CSAM\"","- 原文（Para.6）：\"I would be very cautious [about putting pictures of children online] because there is no protection.\"","- 原文（Para.7-12）：guidance on creating close friends groups, conducting social media audits, reviewing consent forms","分析：","- 选项A：错误。使用了偷换概念陷阱。文章讨论的是AI如何被滥用来危害儿童，而非AI如何\"revolutionizing child protection\"（革新儿童保护），A 项将文章主题（AI滥用威胁）偷换为相反主题（AI保护儿童）。","- 选项B：错误。使用了过度推理陷阱。\"AI生成内容在社交媒体上的兴起\"过于宽泛，文章聚焦的是一个非常具体的子话题——AI生成的儿童性虐待材料（CSAM）及对父母的警告，B 项缺乏针对性。","- 选项C：正确。全文核心论旨是：由于AI可将普通儿童照片转换为CSAM，NCA和IWF敦促父母停止在网上分享孩子照片，并提供了具体的防护指南（创建密友组、社交媒体审计、撤回同意书等）。C 项\"Why Parents Are Urged to Stop Sharing Children's Photos Online\"精准概括了文章主旨——父母为何被敦促停止在网上分享孩子照片。","- 选项D：错误。使用了无中生有陷阱。\"用于检测和移除在线儿童虐待的新技术\"并非文章主题，文章讨论的是预防措施（不给父母发照片的建议）而非检测技术，D 项偏离核心议题。","— — — — — — — — — —","本文档由我们自研的考研英语阅读理解大模型生成。该模型基于近10年考研英语真题进行训练。我们会根据同学们的反馈持续优化模型能力。","本文档为【福利】，不提供答疑服务，欢迎大家自行交流使用。","【两个常见问题】","随着AI技术的不断进步，通过知识投喂和持续训练，大模型已逐渐具备模仿真题命题风格的能力。这份文档正是这一尝试的成果。它仅作为福利提供给大家，起到辅助检验的作用。你可以根据自身需要选择使用，如果有所顾虑，完全可以不用。","如果对答案解析有疑惑，直接打开任何AI大模型（如Deepseek、Kimi等），上传该篇原文文档，然后复制粘贴对应的题目和选项，说清楚你的疑问，大模型会回应解释对应的问题。"]}]}],"qa":[],"originals":[{"kind":"test","label":"检验题","file":"【福利】7.13检验题__完型填空(1).docx","ext":".docx","bytes":63164,"date":"2026-07-13","range":"","title":"","sourcePath":"D:\\外刊\\【福利】7.13检验题__完型填空(1).docx","raw":".cache\\periodical-raw2"},{"kind":"test","label":"检验题","file":"【福利】7.13检验题__阅读理解(1).docx","ext":".docx","bytes":54847,"date":"2026-07-13","range":"","title":"","sourcePath":"D:\\外刊\\【福利】7.13检验题__阅读理解(1).docx","raw":".cache\\periodical-raw2"},{"kind":"layout","label":"杂志排版","file":"7.13杂志排版.pdf","ext":".pdf","bytes":708771,"date":"2026-07-13","range":"","title":"","sourcePath":"D:\\外刊\\7.13杂志排版.pdf","raw":".cache\\periodical-raw2"}]};
